package com.example.user;

public class UserSyncService {
    private final UserRepository repository;
    private final RemoteUserClient remote;

    public UserSyncService(UserRepository repository, RemoteUserClient remote) {
        this.repository = repository;
        this.remote = remote;
    }

    @Transactional
    public void sync(String userId) {
        for (int i = 0; i < 5; i++) {
            try {
                String profile = remote.fetchProfile(userId);
                repository.saveProfile(userId, profile);
                return;
            } catch (Exception ignored) {
            }
        }
    }
}

