public class UserSyncService {
    private final UserRepository repository;
    private final RemoteUserClient remote;
    private final ProfileWriter writer;

    public UserSyncService(UserRepository repository, RemoteUserClient remote) {
        this.repository = repository;
        this.remote = remote;
        this.writer = new ProfileWriter(repository);
    }

    public void sync(String userId) throws IOException {
        for (int attempt = 1; attempt <= 3; attempt++) {
            try {
                String profile = remote.fetchProfile(userId);
                writer.saveProfile(userId, profile);
                return;
            } catch (IOException failure) {
                if (attempt == 3) {
                    throw failure;
                }
            }
        }
    }
